import sys

def is_amplifying(line):
    """Check if a line is an amplifying line."""
    # Remove leading spaces
    stripped = line.lstrip()
    # Check if first character is '#'
    return stripped and stripped[0] == '#'

def process_line(line):
    """Process a single line: remove spaces if not amplifying."""
    if is_amplifying(line):
        return line
    # Remove all spaces
    return line.replace(' ', '')

# Read all lines from input
lines = []
for line in sys.stdin:
    lines.append(line.rstrip('\n'))  # Remove newline at end

# Process each line
processed = []
for line in lines:
    processed.append(process_line(line))

# Concatenate consecutive non-amplifying lines
result = []
for line in processed:
    if is_amplifying(line):
        # If it's an amplifying line, add it as is
        result.append(line)
    else:
        # If it's a non-amplifying line, concatenate with previous non-amplifying line
        if result and not is_amplifying(result[-1]):
            result[-1] += line
        else:
            result.append(line)

# Print the result with newlines
for line in result:
    print(line)
