def can_erase(a, i, j):
    """Check if we can erase elements from position i to j (0-indexed)"""
    n = len(a)

    # Determine min and max values that could fit in the gap
    if i > 0:
        min_gap = a[i-1] + 1
    else:
        min_gap = 1

    if j < n - 1:
        max_gap = a[j+1] - 1
    else:
        max_gap = 1000

    # Number of positions in the gap
    num_positions = j - i + 1

    # Check if there's exactly one way to fill the gap
    return (max_gap - min_gap + 1) == num_positions

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    max_erase = 0

    # Try all possible consecutive segments
    for start in range(n):
        for end in range(start, n):
            if can_erase(a, start, end):
                max_erase = max(max_erase, end - start + 1)

    print(max_erase)

solve()
