import sys

def solve():
    expr = sys.stdin.readline().strip()

    # Try normal evaluation
    try:
        result = eval(expr)
        print(result)
        return
    except:
        pass

    # Try evaluation without respecting operator precedence (left to right)
    tokens = expr.split()
    result = int(tokens[0])
    for i in range(1, len(tokens), 2):
        op = tokens[i]
        num = int(tokens[i+1])
        if op == '+':
            result += num
        elif op == '-':
            result -= num
    print(result)

if __name__ == "__main__":
