def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # a[i] is the old position of the thread now at position i+1 (1-indexed)
    # So thread originally at position p is now at position i where a[i-1] = p

    # For each position i, the thread originally at a[i-1] is now at position i
    # Check if there are any threads with new messages among the threads originally at positions min(i, a[i-1]) to max(i, a[i-1])-1

    new_message_count = 0

    for i in range(1, n+1):
        p = a[i-1]
        if i < p:
            # Check threads originally at positions i to p-1
            # If none of them have new messages, then thread originally at p has a new message
            has_new = False
            for j in range(i, p):
                if new_message_count > 0:
                    has_new = True
                    break
