from itertools import product

def is_square(points):
    """Check if 4 points form a square"""
    dists = []
    for i in range(4):
        for j in range(i + 1, 4):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            dists.append(dx * dx + dy * dy)

    dists.sort()

    # For a square, we should have 4 equal side distances and 2 equal diagonal distances
    # And diagonal distance should be twice the side distance
    if len(dists) != 6:
        return False

    # Check if we have 4 equal smallest distances and 2 equal largest distances
    if dists[0] == dists[1] == dists[2] == dists[3] and dists[4] == dists[5]:
        # Check if diagonals are twice the sides
        if dists[4] == 2 * dists[0]:
            return True

    return False

n = int(sys.stdin.readline())
for _ in range(n):
    points = []
    for _ in range(4):
        x, y, a, b = map(int, sys.stdin.readline().split())
        points.append((x, y, a, b))

    min_moves = float('inf')

    # Try all combinations of moves (0, 1, 2, 3 times for each mole)
    for moves in product(range(4), repeat=4):
        # Calculate positions after applying moves
        positions = []
        for i in range(4):
            x, y, a, b = points[i]
            # Rotate move times
            for _ in range(moves[i]):
                x, y = a + b - y, b + x - a
            positions.append((x, y))

        # Check if positions form a square
        if is_square(positions):
            min_moves = min(min_moves, sum(moves))

    if min_moves != float('inf'):
        print(min_moves)
    else:
        print(-1)
