    valid_intervals = []
    for i in range(n - b + 1):
        start = i + 1
        end = i + b
        # Check if this interval contains any miss
        contains_miss = False
        for j in range(start - 1, end):
            if misses[j] == '1':
                contains_miss = True
                break
        if not contains_miss:
            valid_intervals.append((start, end))

    # Greedy algorithm: select positions that cover the most intervals
    selected = []
    remaining = list(valid_intervals)

    for _ in range(a):
