        return

    # Create checkerboard pattern
    # D positions: (i + j) % 2 == 0
    # R positions: (i + j) % 2 == 1

    seats = [[0 for _ in range(b)] for _ in range(a)]

    # Fill with parliamentarians
    par_num = 1
    for i in range(a):
        for j in range(b):
            if (i + j) % 2 == 0:
                # Democrat position
                if par_num <= n:
                    seats[i][j] = par_num
                par_num += 1

    # Print result
    for row in seats:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
