def kosaraju(graph, n):
    visited = [False] * (n + 1)
    order = []

    def dfs(u):
        stack = [u]
        visited[u] = True
        while stack:
            v = stack[-1]
            has_unvisited = False
            for neighbor in graph[v]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)
                    has_unvisited = True
                    break
            if not has_unvisited:
                stack.pop()
                order.append(v)

