    for u in range(1, n + 1):
        for v in graph[u]:
            reverse_graph[v].append(u)

    visited = [False] * (n + 1)
    scc = []

    def reverse_dfs(u, current_scc):
        stack = [u]
        visited[u] = True
        while stack:
