import sys
from collections import defaultdict, deque

# Parse input
def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    s = int(data[2])

    graph = defaultdict(list)
    idx = 3
    for _ in range(m):
        u = int(data[idx])
        v = int(data[idx + 1])
        graph[u].append(v)
        idx += 2

    # Step 1: Perform DFS to get finishing times
    visited = [False] * (n + 1)
    finish_order = []

    def dfs1(u):
        visited[u] = True
        for v in graph[u]:
            if not visited[v]:
                dfs1(v)
        finish_order.append(u)

    for u in range(1, n + 1):
        if not visited[u]:
            dfs1(u)

    # Step 2: Build reverse graph
    reverse_graph = defaultdict(list)
    for u in range(1, n + 1):
        for v in graph[u]:
            reverse_graph[v].append(u)

    # Step 3: Perform DFS on reverse graph in finish order
    visited = [False] * (n + 1)
    scc = []

    def dfs2(u, current_scc):
        visited[u] = True
        current_scc.append(u)
        for v in reverse_graph[u]:
            if not visited[v]:
                dfs2(v, current_scc)

    for u in reversed(finish_order):
        if not visited[u]:
            current_scc = []
            dfs2(u, current_scc)
            scc.append(current_scc)

    # Find which SCC contains s
    scc_idx = None
    for idx, members in enumerate(scc):
        if s in members:
            scc_idx = idx
            break

    # Build condensation graph (SCC components -> SCC components)
    condensation = defaultdict(list)
    for idx, members in enumerate(scc):
        for u in members:
            for v in graph[u]:
                if scc_map[v] != idx:
                    condensation[idx].append(scc_map[v])

    # Find reachable SCCs from scc_idx using BFS
    reachable_scc = set([scc_idx])
    queue = deque([scc_idx])

    while queue:
        current = queue.popleft()
        for neighbor in condensation[current]:
            if neighbor not in reachable_scc:
                reachable_scc.add(neighbor)
                queue.append(neighbor)

    # Count unreachable SCCs
    unreachable_scc_count = len(scc) - len(reachable_scc)
    print(unreachable_scc_count)

if __name__ == "__main__":
    solve()

