def count_simple_paths(n, edges):
    # Build adjacency list
    graph = [[] for _ in range(n + 1)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Use a stack for DFS to avoid recursion depth issues
    stack = []

    def traverse(current, parent, path):
        path.add(current)
        stack.append((current, parent, path.copy()))

        while stack:
            curr, curr_parent, p = stack.pop()
            if len(p) >= 2:
                # Count a valid path
                total[0] += 1

            for neighbor in graph[curr]:
                if neighbor != curr_parent:
                    new_p = set()
                    for v in p:
                        new_p.add(v)
                    new_p.add(neighbor)
                    stack.append((neighbor, curr, new_p))

    total = [0]  # Use a list to hold the count for mutable access

    for i in range(1, n + 1):
        traverse(i, -1, set())

    return total[0]

