import heapq

def dijkstra(graph, start, max_distance):
    """Find all nodes reachable from start within max_distance"""
    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    heap = [(0, start)]
    reachable = set()

    while heap:
        current_dist, node = heapq.heappop(heap)

        if current_dist > max_distance:
            continue

        if node in reachable:
            continue

        reachable.add(node)

        for neighbor, weight in graph[node].items():
            if current_dist + weight < dist[neighbor]:
                dist[neighbor] = current_dist + weight
                heapq.heappush(heap, (dist[neighbor], neighbor))

    return reachable

def solve():
    n, m = map(int, input().split())
    x, y = map(int, input().split())

    # Build road graph
    road_graph = {i: {} for i in range(1, n+1)}
    for _ in range(m):
        u, v, w = map(int, input().split())
        road_graph[u][v] = w
        road_graph[v][u] = w

    # Build taxi graph
    taxi_graph = {i: [] for i in range(1, n+1)}
    for i in range(1, n+1):
        t, c = map(int, input().split())

        # Find all nodes reachable from i within t meters
        reachable = dijkstra(road_graph, i, t)

        # Add edges to taxi_graph
        for node in reachable:
            taxi_graph[i].append((node, c))

    # Find shortest path in taxi_graph from x to y
    dist = {node: float('inf') for node in taxi_graph}
    dist[x] = 0
    heap = [(0, x)]

    while heap:
        current_cost, node = heapq.heappop(heap)

        if node == y:
            break

        if current_cost > dist[node]:
            continue

        for neighbor, cost in taxi_graph[node]:
            if dist[neighbor] > dist[node] + cost:
                dist[neighbor] = dist[node] + cost
                heapq.heappush(heap, (dist[neighbor], neighbor))

