import sys

def solve():
    n, a, b = map(int, sys.stdin.readline().split())

    # Check if we have enough seats
    if a * b < n:
        print(-1)
        return

    # Create a 2D array of seats
    seats = [[0 for _ in range(b)] for _ in range(a)]

    # Fill in row-major order
    current = 1  # Start with parliamentarian 1
    for row in range(a):
        for col in range(b):
            if current <= n:
                seats[row][col] = current
                current += 1

    # Print the result
    for row in seats:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    solve()
