b = list(map(int, input().split()))
total_soda = sum(a)

# Find minimal k
for k in range(1, n + 1):
    # Use DP to find if there's a subset of size k with capacity >= total_soda
    # We can use a DP table: dp[i][j] = set of bottles that form a subset of size i with capacity j

    # Initialize
    capacity_limit = sum(b) + 1
    dp = [set() for _ in range(k + 1)]
    dp[0].add(0)

    for i in range(n):
        for j in range(k, 0, -1):
            for cap in dp[j - 1]:
                new_cap = cap + b[i]
                dp[j].add(new_cap)
                if new_cap >= total_soda:
                    # Found a valid configuration
                    break
            if total_soda in dp[k]:
                break
        if total_soda in dp[k]:
            break

    if total_soda in dp[k]:
        # Find the subset with maximum sum(a_i)
        # We need to track both capacity and a_sum
        # dp2[i][j] = max a_sum for subset of size i with capacity j
        dp2 = [[-1] * capacity_limit for _ in range(k + 1)]
        dp2[0][0] = 0

        for i in range(n):
            for j in range(k, 0, -1):
                for cap in range(capacity_limit):
                    if dp2[j - 1][cap] != -1:
                        new_cap = cap + b[i]
                        dp2[j][new_cap] = max(dp2[j][new_cap], dp2[j - 1][cap] + a[i])
