def is_square(points):
    dists = []
    for i in range(4):
        for j in range(i + 1, 4):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            dists.append(dx * dx + dy * dy)

    from collections import Counter
    cnt = Counter(dists)

    # Case: 4 distances equal to some s, 2 distances equal to 2s
    if len(cnt) == 2:
        values = list(cnt.values())
        if sorted(values) == [4, 2]:
            return True

    # Case: All 4 points are the same (degenerate square with zero area)
    if len(cnt) == 1 and cnt[0] == 6:
        return False  # Non-zero area required

    return False

def solve():
    n = int(input())
    results = []

    for _ in range(n):
        points = []
        for _ in range(4):
            xi, yi, ai, bi = map(int, input().split())
            points.append((xi, yi, ai, bi))

        min_moves = float('inf')

        # Try all combinations of rotations (0, 1, 2, 3) for each mole
        from itertools import product

        for rotations in product(range(4), repeat=4):
            # Calculate new positions
            new_points = []
            for i in range(4):
                xi, yi, ai, bi = points[i]
                rot = rotations[i]

                # Apply rotation rot times
                for _ in range(rot):
                    # Rotate 90 degrees counter-clockwise around (ai, bi)
                    xi, yi = -yi + bi + ai, xi - ai + bi

                new_points.append((xi, yi))

            # Check if these points form a square
            if is_square(new_points):
                moves = sum(rotations)
                min_moves = min(min_moves, moves)

        if min_moves != float('inf'):
            results.append(str(min_moves))
        else:
            results.append("-1")

    print("\n".join(results))

