import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    grid = data[2:2+n]

    count = 0

    # Try all possible top points (i, j)
    for i in range(n):
        for j in range(m):
            # Try all possible sizes k
            for k in range(1, n + 1):
                # Check if pattern fits
                if i + k - 1 >= n:
                    break
                if j - k + 1 < 0:
                    break
                if j + k - 1 >= m:
                    break

                # Check if all cells in the diamond have the same color
                color = grid[i][j]
                valid = True

                # Check the diamond
                for di in range(k):
                    for dj in range(k):
                        # The diamond has points (i+di, j-dj) and (i+di, j+dj)
                        # Actually, for a diamond of size k, the points are:
                        # (i+di, j - dj) for di from 0 to k-1, dj from 0 to di
                        # (i+di, j + dj) for di from 0 to k-1, dj from 0 to di

                        # We need to check all cells in the diamond
                        # For row i+di, we need to check columns j - di to j + di
                        row = i + di
                        col = j - dj
                        if col >= 0 and grid[row][col] == color:
                            continue
                        else:
                            valid = False
                            break
                    if not valid:
                        break

                for di in range(k):
                    for dj in range(k):
                        row = i + di
                        col = j + dj
                        if col < m and grid[row][col] == color:
                            continue
                        else:
                            valid = False
                            break
                    if not valid:
                        break

                if valid:
                    count += 1

    print(count)

