def count_indentations(N, commands):
    MOD = 10**9 + 7

    # dp[i] = number of ways to parse the first i commands (0-indexed)
    dp = [0] * (N + 1)
    dp[0] = 1

    for i in range(1, N + 1):
        if commands[i-1] == 's':
            # simple statement at current level
            dp[i] = dp[i-1]
        else:
            # for statement: need a body that starts at the next indentation level
            # and has at least one statement
            for j in range(1, i-1):
                # dp[j] = number of ways to reach the current indentation level
                # commands[i-1-j-1] = 'f' should be the start of the for statement
                if commands[i-1-j-1] == 'f':
                    dp[i] = (dp[i] + dp[j] * dp[i-1-j]) % MOD

    return dp[N]

N = int(input())
commands = [input().strip() for _ in range(N)]
print(count_indentations(N, commands))
"}

