import sys

def parse_action(action):
    """Parse an action string to get X and Y"""
    words = action.split()

    # X is the first word
    x = words[0]

    # Y is the word before 'wall' or 'post'
    # Look for 'wall', 'post', or 'likes' (but 'likes' is the verb)
    # Actually, 'post' can be part of 'posted' or 'post'
    # Let's look for the word before 'wall'
    for i, word in enumerate(words):
        if word == "wall":
            y = words[i-1]
            return x, y
        elif word == "post":
            y = words[i-1]
            return x, y

    # If we didn't find it, look for 'likes' as the verb
    # 'likes' can be the verb or part of 'posted's post'
    if 'likes' in words:
        # Look for the word before 'likes'
        for i, word in enumerate(words):
            if word == "likes":
                # The subject is before 'likes'
                x = words[i-1]
                # The object is after 'likes'
                # It's the word before 'wall' or 'post'
                for j, word2 in enumerate(words[i+1:], start=i+1):
                    if word2 == "wall" or word2 == "post":
                        y = words[j-1]
                        return x, y

    raise ValueError(f"Could not parse action: {action}")

# Read input
your_name = input().strip()
n = int(input().strip())

# Initialize priority dictionary
priority = {}

for _ in range(n):
    action = input().strip()
    x, y = parse_action(action)

    # Add points to both X and Y
    # X -> Y
    if x not in priority:
        priority[x] = {}
    if y not in priority[x]:
        priority[x][y] = 0
    priority[x][y] += 15 if 'post' in action or 'posted' in action else 10 if 'comment' in action else 5

    # Y -> X
    if y not in priority:
        priority[y] = {}
    if x not in priority[y]:
        priority[y][x] = 0
    priority[y][x] += 15 if 'post' in action or 'posted' in action else 10 if 'comment' in action else 5

# Collect all distinct names (excluding yourself)
all_names = set()
for person in priority:
    if person != your_name:
        all_names.add(person)
    for friend in priority[person]:
