import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    heights = list(map(int, data[1:1+n]))

    # Sort the heights
    heights.sort()

    # For n=2, just return the sorted list
    if n == 2:
        return heights

    # Create the result array that minimizes the max difference
    # Start with the two largest elements
    # Go around clockwise

    if n % 2 == 0:
        # n is even
        result = [heights[n-1]]
        # Place the two largest together
        if n > 3:
            result.append(heights[n-2])

        # Fill the rest
        for i in range(n-2):
            if (i+1) % 2 == 0:
                result.append(heights[n-3 - (i//2)])
            else:
                result.append(heights[i//2])
    else:
        # n is odd
        result = [heights[0]]

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
