def is_caterpillar(tree):
    # Count degrees
    degrees = [0] * (len(tree) + 1)
    for u in range(1, len(tree) + 1):
        for v in tree[u]:
            degrees[u] += 1
            degrees[v] += 1

    # Remove leaves (degree 1)
    leaves = [i for i in range(1, len(tree) + 1) if degrees[i] == 1]
    for leaf in leaves:
        for neighbor in tree[leaf]:
            degrees[neighbor] -= 1

    # Check if remaining is a path
    for i in range(1, len(tree) + 1):
        if degrees[i] > 2:
            return False

    # Check connectivity (using BFS)
    visited = set()
    queue = [1]  # start from any vertex
    while queue:
        u = queue.pop(0)
        if u in visited:
            continue
        visited.add(u)
        for v in tree[u]:
            if degrees[v] > 0 and v not in visited:
                queue.append(v)

    return len(visited) == len(tree)

