def compute_balance_min(s):
    balance = 0
    min_balance = 0
    for ch in s:
        if ch == '(':
            balance += 1
        else:
            balance -= 1
        min_balance = min(min_balance, balance)
    return balance, min_balance

def solve():
    n = int(input())
    from collections import defaultdict
    count = defaultdict(int)

    for _ in range(n):
        s = input().strip()
        b, m = compute_balance_min(s)
        count[(b, m)] += 1

    result = 0

    # For balance 0, we need pairs of sequences that are both valid
    if (0, 0) in count:
        result += count[(0, 0)] // 2

    # For other balances, we look for pairs (b, m) and (-b, m')
    for b, m in count:
        if b > 0:
            # Need pair with balance -b and min_balance >= -b
            cnt_neg_b = count.get((-b, -b), 0)
            result += cnt_neg_b
        elif b < 0:
            # Need pair with balance -b and min_balance >= 0
            cnt_b = count.get((-b, 0), 0)
            result += cnt_b

    print(result)

solve()
