def is_square(p1, p2, p3, p4):
    """Check if 4 points form a square"""
    def dist2(p, q):
        return (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2

    # Calculate all pairwise squared distances
    d = [dist2(p1, p2), dist2(p1, p3), dist2(p1, p4),
         dist2(p2, p3), dist2(p2, p4), dist2(p3, p4)]

    # There should be exactly 2 distinct distances
    unique_d = list(set(d))
    if len(unique_d) != 2:
        return False

    # The larger distance should be the diagonal (sqrt(2) times the side length)
    side2, diag2 = sorted(unique_d)
    if diag2 != 2 * side2:
        return False

    return True

def rotate(x, y, a, b, moves):
    """Rotate a point (x, y) around home (a, b) moves times"""
    for _ in range(moves):
        x, y = a - y + b, b + x - a
    return x, y

