    difficulties = list(map(int, input().split()))

    # Group tasks by difficulty
    from collections import defaultdict
    task_groups = defaultdict(list)
    for i, diff in enumerate(difficulties):
        task_groups[diff].append(i + 1)  # 1-indexed task numbers

    # Check if we can get at least 3 distinct sequences
    can_get_three = False

    # Count frequencies
    freq = {}
    for diff in task_groups:
        freq[diff] = len(task_groups[diff])

    # Check conditions
    # Condition 1: at least one difficulty with >= 3 tasks
    if any(count >= 3 for count in freq.values()):
        can_get_three = True

    # Condition 2: at least two different difficulties with >= 2 tasks each
    if not can_get_three:
        counts = [v for v in freq.values() if v >= 2]
        if len(counts) >= 2:
            can_get_three = True

    if not can_get_three:
        print("NO")
        return

    print("YES")

    # Get all groups with 2+ tasks
    groups_with_permutations = []
    for diff in sorted(freq.keys()):
        if len(task_groups[diff]) >= 2:
            groups_with_permutations.append(task_groups[diff])

    # There should be exactly one group
    if len(groups_with_permutations) != 1:
        group = [1, 2, 3, 4]  # fallback
    else:
        group = groups_with_permutations[0]

