    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        # Skip empty line
        while True:
            try:
                token = next(it)
                if token == "":
                    continue
                elif token == "\n":
                    continue
                else:
                    break
            except StopIteration:
                break

        n = int(next(it))
        m = int(next(it))

        # Read m blocked cells
        blocked = []
        for _ in range(m):
            r = int(next(it))
            c = int(next(it))
            blocked.append((r, c))

        # Check if we can tile
        if m == 0:
            print("YES")
        elif m % 2 != 0:
            print("NO")
        elif m == 2:
            # Check if the two blocked cells are in the same column
            r1, c1 = blocked[0]
            r2, c2 = blocked[1]
            if c1 == c2:
                print("YES")
            else:
                print("NO")
        else:
            print("NO")

if __name__ == "__main__":
