import sys

def smallest_number(n_str):
    if n_str == '0':
        return '0'

    digits = list(n_str)

    # Sort all digits
    digits.sort()

    # If first digit is 0, find the smallest non-zero and move it to front
    # We need to find the smallest non-zero digit (could be '1' or something else)
    # and move it to the front
    if digits[0] == '0':
        # Find the index of the smallest non-zero digit
        smallest_non_zero = min([d for d in digits if d != '0'])
        idx = digits.index(smallest_non_zero)

        # Swap with the first position
        digits[0], digits[idx] = digits[idx], digits[0]

    # Sort the remaining digits
    for i in range(1, len(digits)):
        if i == 0:
            continue

        for j in range(i, len(digits)):
            digits[i], digits[j] = digits[j], digits[i]

    return ''.join(digits)

def main():
    input_lines = sys.stdin.read().strip().split('\n')

    if len(input_lines) < 2:
        return

    n = input_lines[0].strip()
    m = input_lines[1].strip()

    expected = smallest_number(n)

    # Check if expected matches m (without removing leading zeros this time)
    if expected == m:
        print("OK")
    else:
        print("WRONG_ANSWER")

