import math

def rotate(x, y, a, b, moves):
    """Rotate point (x, y) moves times around home (a, b)"""
    for _ in range(moves):
        # Rotate 90 degrees counter-clockwise
        x, y = a + b - y, b + x - a
    return x, y

def is_square(p1, p2, p3, p4):
    """Check if 4 points form a square"""
    points = [p1, p2, p3, p4]

    # Check all 4! = 24 permutations
    # The square vertices: A, B, C, D should satisfy: distance(A,B) = distance(B,C) = distance(C,D) = distance(D,A)
    # And distance(A,C) = distance(B,D)
    # And the dot product of AB and AD should be 0

    for a in range(4):
        for b in range(4):
            if a == b:
                continue
            for c in range(4):
                if c == a or c == b:
                    continue
                for d in range(4):
                    if d == a or d == b or d == c:
                        continue
                    # The order: a -> b -> c -> d -> a
                    ab = math.hypot(points[b][0] - points[a][0], points[b][1] - points[a][1])
                    bc = math.hypot(points[c][0] - points[b][0], points[c][1] - points[b][1])
                    cd = math.hypot(points[d][0] - points[c][0], points[d][1] - points[c][1])
                    da = math.hypot(points[a][0] - points[d][0], points[a][1] - points[d][1])

                    # If all sides are equal
                    if abs(ab - bc) < 1e-9 and abs(bc - cd) < 1e-9 and abs(cd - da) < 1e-9:
                        # Check diagonals
                        ac = math.hypot(points[c][0] - points[a][0], points[c][1] - points[a][1])
                        bd = math.hypot(points[d][0] - points[b][0], points[d][1] - points[b][1])

                        if abs(ac - bd) < 1e-9:
                            # Check that sides are perpendicular
                            # Vectors: AB and AD
                            abv = (points[b][0] - points[a][0], points[b][1] - points[a][1])
                            adv = (points[d][0] - points[a][0], points[d][1] - points[a][1])
                            dot = abv[0] * adv[0] + abv[1] * adv[1]

                            if abs(dot) < 1e-9:
