        if dist[u][v] > w:
            dist[u][v] = w
        if dist[v][u] > w:
            dist[v][u] = w

    # Floyd-Warshall
    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Read taxis
    taxis = []
    for i in range(1, n + 1):
        ti, ci = map(int, input().split())
        taxis.append((ti, ci))

    # Dijkstra's algorithm
    # State: (total_cost, current_junction, remaining_distance)
    # Initially: we are at junction x with unlimited remaining distance
    heap = [(0, x, INF)]
    visited = [False] * (n + 1)

    while heap:
