        # We need to ensure both have the same value
        # Count how many times each value appears in each pair
        pairs = {}

        for i in range(n):
            for j in range(m):
                # Skip if we've already processed this pair
                sym_i = n + m - 1 - i
                sym_j = n + m - 1 - j
                if sym_i < n or sym_j < m or (sym_i, sym_j) in pairs:
                    continue

                # Count occurrences of 0 and 1 in this pair
                count_0 = 0
                count_1 = 0

                # Check both cells in the pair
                for (x, y) in [(i, j), (sym_i, sym_j)]:
                    if x < n and y < m:
                        val = matrix[x][y]
                        if val == 0:
