def solve():
    import sys
    input = sys.stdin.read().split()
    data = iter(input)

    t = int(next(data))

    for _ in range(t):
        n = int(next(data))
        parent = [0] * (n + 1)
        for i in range(2, n + 1):
            parent[i] = int(next(data))

        a = [0] * (n + 1)
        for i in range(2, n + 1):
            a[i] = int(next(data))

        # Build tree
        tree = [[] for _ in range(n + 1)]
        for i in range(2, n + 1):
            tree[parent[i]].append(i)

        # Find depth of each node
        depth = [0] * (n + 1)
        for i in range(2, n + 1):
            depth[i] = depth[parent[i]] + 1

        # Group nodes by depth
        depth_nodes = [[] for _ in range(n + 1)]
        for i in range(1, n + 1):
            depth_nodes[depth[i]].append(i)

        # DP: dp[depth][u][v] = max points
        # Since depth is up to 200,000, we need to be careful
        # We'll use a dictionary for current and next states

        # Base case: both at root (depth 0)
        current = {(1, 1): 0}

        for depth in range(0, n - 1):  # we make n-1 moves
            next_state = {}

            for (u, v), score in current.items():
                # Move red coin to any child of u
                for child in tree[u]:
                    # Move blue coin to any node at depth+1
                    for node in depth_nodes[depth + 1]:
                        new_score = score + abs(a[child] - a[node])
                        if (child, node) not in next_state:
                            next_state[(child, node)] = new_score
                        else:
                            next_state[(child, node)] = max(new_score, next_state[(child, node)])

            # Also consider swapping
            for (u, v), score in current.items():
                # Move red coin to any child of u
                for child in tree[u]:
                    # Move blue coin to any node at depth+1
                    for node in depth_nodes[depth + 1]:
                        # Swap after move
                        new_score = score + abs(a[child] - a[node])
                        if (node, child) not in next_state:
                            next_state[(node, child)] = new_score
                        else:
                            next_state[(node, child)] = max(new_score, next_state[(node, child)])

            current = next_state

        # The answer is the maximum score at depth n-1
        if current:
            print(max(current.values()))
        else:
            print(0)

