def solve():
    import sys
    input = sys.stdin.read().split()
    it = iter(input)

    def next_int():
        return int(next(it))

    t = next_int()
    out_lines = []

    for _ in range(t):
        n = next_int()
        parent = [0] * n  # parent[0] unused
        for i in range(1, n):
            parent[i] = next_int()
        a = [0] * n
        for i in range(1, n):
            a[i] = next_int()

        # Compute distance from root
        dist = [0] * n

        def dfs(u, depth):
            dist[u] = depth
            for v in range(1, n):
                if parent[v] == u:
                    dfs(v, depth + 1)

        dfs(0, 0)

        # Group by distance
        levels = [[] for _ in range(n)]
        for i in range(1, n):
            levels[dist[i]].append(a[i])

        # For each distance, find best pair (max and min)
        total = 0
        for i in range(1, n):
            if len(levels[i]) >= 2:
                max_val = max(levels[i])
                min_val = min(levels[i])
                total += max_val - min_val

        out_lines.append(str(total))

    sys.stdout.write("\n".join(out_lines))

