def is_palindrome(s):
    return s == s[::-1]

def solve():
    n = int(sys.stdin.readline())
    digits = list(map(int, sys.stdin.readline().split()))
    digit_strs = [str(d) for d in digits]

    beautiful_ips = []

    # Try all combinations of part lengths (1, 2, or 3 digits per part)
    for part1_len in range(1, 4):
        for part2_len in range(1, 4):
            for part3_len in range(1, 4):
                for part4_len in range(1, 4):
                    total_length = part1_len + part2_len + part3_len + part4_len

                    # Try all permutations of the digits
                    from itertools import permutations
                    for perm in permutations(digit_strs):
                        # Split the permutation into parts
                        part1 = perm[:part1_len]
                        part2 = perm[part1_len:part1_len+part2_len]
                        part3 = perm[part1_len+part2_len:part1_len+part2_len+part3_len]
                        part4 = perm[part1_len+part2_len+part3_len:]

                        # Check for leading zeros
                        if len(part1) > 1 and part1[0] == '0':
                            continue
                        if len(part2) > 1 and part2[0] == '0':
                            continue
                        if len(part3) > 1 and part3[0] == '0':
                            continue
                        if len(part4) > 1 and part4[0] == '0':
