import sys

def is_amplifying(line):
    """Check if a line is amplifying."""
    stripped = line.lstrip()
    return stripped and stripped[0] == '#'

def process_line(line):
    """Process a single line."""
    if is_amplifying(line):
        return line
    # Remove all spaces from non-amplifying line
    return line.replace(' ', '')

def main():
    lines = []
    for line in sys.stdin:
        lines.append(line.rstrip('\n'))  # Remove newline at end of line

    processed = []
    current = ''

    for line in lines:
        if is_amplifying(line):
            # If we have accumulated non-amplifying lines, add them
            if current:
                processed.append(current)
                current = ''
            processed.append(line)
        else:
            # Process non-amplifying line
            processed_line = process_line(line)
            current += processed_line

    # Add any remaining accumulated non-amplifying lines
    if current:
        processed.append(current)

