import heapq

def dijkstra(n, adj, start):
    """Dijkstra's algorithm to find shortest paths from start to all other nodes"""
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    heap = [(0, start)]

    while heap:
        current_dist, u = heapq.heappop(heap)
        if current_dist > dist[u]:
            continue

        for v, weight in adj[u]:
            if dist[v] > dist[u] + weight:
                dist[v] = dist[u] + weight
                heapq.heappush(heap, (dist[v], v))

    return dist

def solve():
    n, m = map(int, input().split())
    x, y = map(int, input().split())

    # Build adjacency list for roads
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, v, w = map(int, input().split())
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Precompute shortest paths between all pairs using Floyd-Warshall
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dist[i][i] = 0

    for u in range(1, n + 1):
        for v in range(1, n + 1):
            if adj[u]:
                for neighbor, weight in adj[u]:
                    if dist[u][v] > dist[u][neighbor] + weight:
                        dist[u][v] = dist[u][neighbor] + weight

    # Read taxi information
    taxi = []
    for _ in range(n):
        ti, ci = map(int, input().split())
        taxi.append((ti, ci))

    # Dijkstra's algorithm to find minimum cost
    min_cost = [float('inf')] * (n + 1)
    min_cost[x] = 0
    heap = [(0, x)]

    while heap:
        cost, u = heapq.heappop(heap)
        if cost > min_cost[u]:
            continue

        # Try to use taxi at junction u to reach other junctions
        for v in range(1, n + 1):
            if dist[u][v] <= taxi[u-1][0]:
                new_cost = cost + taxi[u-1][1]
                if new_cost < min_cost[v]:
                    min_cost[v] = new_cost
                    heapq.heappush(heap, (new_cost, v))

    if min_cost[y] == float('inf'):
        print(-1)
    else:
        print(min_cost[y])

solve()
