        if diff not in freq:
            freq[diff] = []
        freq[diff].append(i + 1)  # 1-indexed task numbers

    # Check if we can get at least 3 distinct permutations
    product = 1
    for group in freq.values():
        product *= factorial(len(group))

    if product < 3:
        print("NO")
        return

    print("YES")

    # Construct the first plan
    # Sort by difficulty, then by original index
    tasks = []
    for diff in sorted(freq.keys()):
        for task_num in sorted(freq[diff]):
            tasks.append(task_num)

