for _ in range(n):
    k, a = map(int, input().split())
    boxes[k] = a

# Start from the smallest size and work our way up
# We need to track how many boxes we have at each size
box_counts = {}
for k in sorted(boxes.keys()):
    box_counts[k] = boxes[k]

# Work our way up from the smallest size
for k in sorted(boxes.keys()):
    # Calculate how many boxes of size k we need at size k+1
    needed = (box_counts[k] + 3) // 4  # Round up division

    # If we don't have enough boxes of size k+1, we need to create more
    if k + 1 in box_counts:
        box_counts[k + 1] += needed
    else:
        box_counts[k + 1] = needed

# Find the smallest size that can contain all boxes
# This is the largest k where box_counts[k] > 0
result = max(k for k, count in box_counts.items() if count > 0)

print(result)
