    m = int(data[1])

    pairs = []
    idx = 2
    for _ in range(m):
        a = int(data[idx])
        b = int(data[idx + 1])
        pairs.append((a, b))
        idx += 2

    # Try all possible x values
    candidates = set(a for a, b in pairs) | set(b for a, b in pairs)
    for x in candidates:
        # Collect pairs that don't contain x
        non_covered = []
        for a, b in pairs:
            if a != x and b != x:
                non_covered.append((a, b))

        if not non_covered:
            # All pairs contain x, we can pick any y
            print("YES")
            return

        # Find the common element in all non-covered pairs
        common = set(non_covered[0])
        for a, b in non_covered[1:]:
            common &= set([a, b])
            if not common:
                break

        if common:
            # Check if all pairs that don't contain x contain the common element
            y = common.pop()
            valid = True
            for a, b in pairs:
                if a != x and b != x and a != y and b != y:
                    valid = False
                    break
            if valid:
                print("YES")
                return

    print("NO")

if __name__ == "__main__":
    solve()
