import sys

def is_amplifying(line):
    """Check if a line is amplifying."""
    # Remove leading spaces
    stripped = line.lstrip()
    # If the stripped line starts with '#', it's amplifying
    return stripped.startswith('#')

def process_spell(lines):
    """Process the spell according to the rules."""
    processed = []
    i = 0
    n = len(lines)

    while i < n:
        line = lines[i].rstrip('\n')  # Remove newline from the end

        if is_amplifying(line):
            # Amplifying line: preserve it
            processed.append(line)
            i += 1
        else:
            # Non-amplifying line: remove spaces
            stripped = line.replace(' ', '')

            # Check if we need to merge with previous lines
            if processed and not is_amplifying(processed[-1]):
                # Previous line is non-amplifying, merge
                processed[-1] += stripped
            else:
                # Start new non-amplifying block or after amplifying line
                processed.append(stripped)
            i += 1

    return processed

def main():
    lines = []
    for line in sys.stdin:
        lines.append(line)

    processed = process_spell(lines)

    for line in processed:
        print(line)

if __name__ == "__main__":
    main()
"}

