n, m, k, q = map(int, input().split())

# Create a grid to store the latest time each pixel becomes broken
# Initially, all pixels are unbroken (time = -1)
grid = [[-1 for _ in range(m)] for _ in range(n)]

for _ in range(q):
    x, y, t = map(int, input().split())
    # Convert to 0-indexed
    grid[x-1][y-1] = t

min_time = float('inf')

# Check all possible k×k squares
for i in range(n - k + 1):
    for j in range(m - k + 1):
        # Check if all pixels in this square are broken
        all_broken = True
        max_time = -1
        for dx in range(k):
            for dy in range(k):
                x = i + dx
                y = j + dy
                if grid[x][y] == -1:
                    all_broken = False
                    break
                if grid[x][y] > max_time:
                    max_time = grid[x][y]
            if not all_broken:
                break

        if all_broken:
            min_time = min(min_time, max_time)

if min_time == float('inf'):
    print(-1)
else:
    print(min_time)
