import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    for num in arr:
        valid = True
        for other in arr:
            if other % num != 0:
                valid = False
                break
        if valid:
            print(num)
            return

    print(-1)

if __name__ == "__main__":
    solve()
"}

